      'async function processarFila(jobs, executar, maxTentativas) {\n  const ok = [];\n  const falhas = [];\n  for (const job of jobs) {\n    let sucesso = false;\n    for (let t = 1; t <= maxTentativas && !sucesso; t++) {\n      try {\n        await executar(job);\n        sucesso = true;\n      } catch {\n        // tenta de novo\n      }\n    }\n    (sucesso ? ok : falhas).push(job.id);\n  }\n  return { ok, falhas };\n}',
